import{_ as t,o,c as a,a2 as s}from"./chunks/framework.CyZTVJbV.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.23/x-thread-en.md","filePath":"announcements/v1.23/x-thread-en.md"}'),c={name:"announcements/v1.23/x-thread-en.md"};function i(d,e,n,r,l,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<p>1/ kiwa v1.23 is out — Payment 深化 milestone. After v1.14&#39;s payment webhook mock landed the 3 provider baseline (Stripe + Paddle + Lemon Squeezy signature verify + 4 fixture events), v1.23 layers <strong>9 axes of advanced billing semantics</strong> on top — dunning + retry + 3DS v2 + SCA + PSD2 mandate + subscription lifecycle + invoice lifecycle + VAT/GST/sales-tax + chargeback dispute. Provider-neutral state machines + strict transition guards. 100 new semantics tests.</p><p>2/ Why 9 axes? Real billing has 3 failure modes a webhook-only mock can&#39;t catch — state-machine drift (a subscription&#39;s real lifecycle is a 5-state graph with guards, not <code>active</code>/<code>canceled</code>), retry cadence (real dunning = 4 attempts over ~1 week + grace period), cross-provider fidelity (Stripe defers proration; Paddle charges immediately; Lemon Squeezy hosts checkout while Paddle inlines it). Each axis is a pure module under <code>@kiwa-test/payment/semantics/*</code> that emits a strongly typed <code>AxisStep</code> sequence.</p><p>3/ v1.23-1 <code>@kiwa-test/payment</code> v0.3 lands the 9 semantics files (<code>dunning.ts</code> / <code>retry.ts</code> / <code>three-ds.ts</code> / <code>sca.ts</code> / <code>psd2.ts</code> / <code>subscription-lifecycle.ts</code> / <code>invoice.ts</code> / <code>tax.ts</code> / <code>chargeback.ts</code>) + 3-provider neutral event routing table (34 neutral events × 3 provider = 102 entries) + fidelity harness <code>collectFidelityCoverage()</code> 3 × 9 = 27 rows for the release gate. 118/118 tests pass (base 18 + new 100).</p><p>4/ v1.23-2 dogfood-stripe-billing-app — Next.js 15 App Router + Stripe checkout session + webhook endpoint + subscription lifecycle + invoice + 3D Secure v2 + Smart Retries dunning. 35 vitest exercising the full envelope through <code>createStripeMock</code>. <code>KIWA_MODE=real</code> flips the same tests to hit the actual Stripe sandbox without touching bodies.</p><p>5/ v1.23-3 dogfood-paddle-merchant-app — Nuxt 3 + Paddle Billing v2 + inline checkout (<code>Paddle.Checkout.open</code>) + tier upgrade with proration + VAT/GST/sales-tax auto-calc + reverse-charge B2B EU customers. 40 vitest. Paddle acts as Merchant-of-Record — app never touches PSP details, mock reproduces the neutralised events.</p><p>6/ v1.23-4 dogfood-lemon-squeezy-app — SvelteKit + hosted checkout + license key issue+activate+revoke + refund full+partial + chargeback dispute lifecycle (opened → evidence-submitted → won/lost + fee assessment). 74 vitest — the widest dogfood app of v1.23 because license flow doubles as chargeback signal source.</p><p>7/ v1.23-5 docs — 3 new tutorials (39 Stripe advanced billing + 40 Paddle merchant-of-record + 41 Lemon Squeezy license flow), 1 concept doc <code>billing-semantics.md</code> (9-axis SSOT + provider-specific fidelity surface reference), migration guide v1.22 → v1.23 (additive-only), snippet validation test <code>docs-tutorial-v1.23.test.ts</code> (18 test) that re-runs every code snippet against the real <code>@kiwa-test/payment</code> API. Same drift-detection pattern as <code>docs-tutorial-v1.21.test.ts</code> and <code>docs-tutorial-v1.22.test.ts</code>.</p><p>8/ 1 npm minor bump — <code>@kiwa-test/payment</code> v0.2.0 → v0.3.0 published to npm. Additive-only: v0.2 webhook mock + 4 fixture events (<code>checkoutCompleted</code> / <code>subscriptionCreated</code> / <code>paymentFailed</code> / <code>refunded</code>) keep every prior signature. VitePress sidebar gains <code>Payment 深化 (v1.23)</code> tutorial section + <code>billing-semantics.md</code> under Concepts + <code>v1.22 → v1.23</code> under Migrations. gh-pages published. Roadmap: <a href="https://github.com/cardene777/kiwa#roadmap" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa#roadmap</a> — v1.11 → v1.12 → v1.13 → v1.14 → v1.15 → v1.16 → v1.17 → v1.18 → v1.19 → v1.20 → v1.21 → v1.22 → v1.23: 13 milestones in a row.</p>',8)])])}const m=t(c,[["render",i]]);export{v as __pageData,m as default};
